/**
 * Adopt the UIScene life cycle on iOS (ASK_FOR_QUOTES_PLAN §3).
 *
 * The iOS 27 SDK asserts at launch unless an app uses scenes. Expo 57 ships
 * the scene delegate itself (`ExpoAppSceneDelegate`: it creates the window
 * from the connecting scene, starts React Native, rebuilds launch options so
 * a cold-start link reaches `Linking.getInitialURL()`, and forwards URLs,
 * universal links, quick actions and life-cycle events to `ExpoAppDelegate`).
 * Expo 57's project template does not use it yet, and `ios/` is generated by
 * `expo prebuild`, so this plugin does what the Expo 58 template does:
 *
 *   - Info.plist: one application scene whose delegate is `SceneDelegate`;
 *   - SceneDelegate.swift: `class SceneDelegate: ExpoAppSceneDelegate {}`,
 *     added to the app target;
 *   - AppDelegate.swift: conform to `ExpoReactNativeFactoryProvider`, keep
 *     creating the factory, stop creating the window and starting React
 *     Native, and drop the URL and universal-link overrides (the scene
 *     delegate forwards those now).
 *
 * Idempotent, and a no-op for a project that already adopts scenes (the
 * Expo 58 template), at which point this plugin should be deleted.
 */

const fs = require('fs');
const path = require('path');

const {
  IOSConfig,
  withAppDelegate,
  withDangerousMod,
  withInfoPlist,
  withXcodeProject,
} = require('expo/config-plugins');

const SCENE_DELEGATE_FILE = 'SceneDelegate.swift';

const SCENE_DELEGATE_SOURCE = `internal import Expo

// Created by the with-scene-lifecycle config plugin (apps/mobile/plugins).
// ExpoAppSceneDelegate creates the window from the connecting scene, starts
// React Native, and forwards links and life-cycle events to the app delegate.
@objc(SceneDelegate)
class SceneDelegate: ExpoAppSceneDelegate {
  // Extension point for config plugins.
}
`;

const SCENE_MANIFEST = {
  UIApplicationSupportsMultipleScenes: false,
  UISceneConfigurations: {
    UIWindowSceneSessionRoleApplication: [
      {
        UISceneConfigurationName: 'Default Configuration',
        UISceneDelegateClassName: '$(PRODUCT_MODULE_NAME).SceneDelegate',
      },
    ],
  },
};

/** The window block the pre-scene template writes in didFinishLaunching. */
const WINDOW_BLOCK =
  /\n#if os\(iOS\) \|\| os\(tvOS\)\n\s*window = UIWindow\(frame: UIScreen\.main\.bounds\)\n\s*factory\.startReactNative\(\n\s*withModuleName: "main",\n\s*in: window,\n\s*launchOptions: launchOptions\)\n#endif\n\n/;

/** The Linking API and Universal Links overrides of the pre-scene template. */
const LINK_OVERRIDES =
  /\n\s*\/\/ Linking API\n\s*public override func application\(\n\s*_ app: UIApplication,\n\s*open url: URL,[\s\S]*?\n {2}}\n\n\s*\/\/ Universal Links\n\s*public override func application\([\s\S]*?restorationHandler: restorationHandler\) \|\| result\n {2}}\n/;

/**
 * Rewrite a pre-scene AppDelegate.swift for the scene life cycle. Throws when
 * the file matches neither the pre-scene template nor an adopted one, so a
 * changed template is noticed at prebuild instead of shipping half-edited.
 */
function adoptSceneLifecycle(contents) {
  if (contents.includes('ExpoReactNativeFactoryProvider')) return contents; // already adopted
  const declaration = 'class AppDelegate: ExpoAppDelegate {';
  if (!contents.includes(declaration) || !WINDOW_BLOCK.test(contents)) {
    throw new Error(
      'with-scene-lifecycle: AppDelegate.swift does not match the Expo template it knows; ' +
        'update the plugin (or delete it if the template already adopts scenes).',
    );
  }
  return contents
    .replace(declaration, 'class AppDelegate: ExpoAppDelegate, ExpoReactNativeFactoryProvider {')
    .replace(
      WINDOW_BLOCK,
      '\n    // The window is created and React Native is started by `SceneDelegate` under the\n' +
        '    // scene-based life cycle (required by the iOS 27 SDK).\n',
    )
    .replace(LINK_OVERRIDES, '\n');
}

function withSceneManifest(config) {
  return withInfoPlist(config, (cfg) => {
    cfg.modResults.UIApplicationSceneManifest = SCENE_MANIFEST;
    return cfg;
  });
}

function withSceneDelegateFile(config) {
  return withDangerousMod(config, [
    'ios',
    async (cfg) => {
      const projectName = IOSConfig.XcodeUtils.getProjectName(cfg.modRequest.projectRoot);
      const file = path.join(cfg.modRequest.platformProjectRoot, projectName, SCENE_DELEGATE_FILE);
      fs.writeFileSync(file, SCENE_DELEGATE_SOURCE);
      return cfg;
    },
  ]);
}

function withSceneDelegateInProject(config) {
  return withXcodeProject(config, (cfg) => {
    const project = cfg.modResults;
    const projectName = IOSConfig.XcodeUtils.getProjectName(cfg.modRequest.projectRoot);
    const filepath = `${projectName}/${SCENE_DELEGATE_FILE}`;
    if (!project.hasFile(filepath)) {
      IOSConfig.XcodeUtils.addBuildSourceFileToGroup({
        filepath,
        groupName: projectName,
        project,
      });
    }
    return cfg;
  });
}

function withSceneAppDelegate(config) {
  return withAppDelegate(config, (cfg) => {
    if (cfg.modResults.language !== 'swift') {
      throw new Error('with-scene-lifecycle: expected a Swift AppDelegate');
    }
    cfg.modResults.contents = adoptSceneLifecycle(cfg.modResults.contents);
    return cfg;
  });
}

function withSceneLifecycle(config) {
  return withSceneAppDelegate(
    withSceneDelegateInProject(withSceneDelegateFile(withSceneManifest(config))),
  );
}

module.exports = withSceneLifecycle;
module.exports.adoptSceneLifecycle = adoptSceneLifecycle;
module.exports.SCENE_MANIFEST = SCENE_MANIFEST;
module.exports.SCENE_DELEGATE_SOURCE = SCENE_DELEGATE_SOURCE;
